import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { ContentPart } from '../types';

/**
 * Generates a chat response from the Gemini model.
 * @param ai The GoogleGenAI instance.
 * @param prompt The user's message.
 * @param systemInstruction The system instruction for the chat.
 * @param modelName The name of the Gemini model to use for chat.
 * @returns The text response from Ani.
 */
export async function generateChatResponse(
  ai: GoogleGenAI,
  prompt: string,
  systemInstruction: string,
  modelName: string
): Promise<string> {
  try {
    const chat = ai.chats.create({
      model: modelName,
      config: {
        systemInstruction: systemInstruction,
      },
    });

    const response: GenerateContentResponse = await chat.sendMessage({ message: prompt });
    return response.text || "Ani est muette, c'est ouf ! ♥♥";
  } catch (error) {
    console.error("Erreur Gemini Chat:", error);
    throw error;
  }
}

/**
 * Generates or edits an image using the Gemini model.
 * @param ai The GoogleGenAI instance.
 * @param base64Image The base64 encoded image data.
 * @param mimeType The MIME type of the image (e.g., 'image/png', 'image/jpeg').
 * @param prompt The text prompt for image editing/generation.
 * @param modelName The name of the Gemini model to use for image editing.
 * @returns The base64 encoded string of the edited image.
 */
export async function generateImageEditResponse(
  ai: GoogleGenAI,
  base64Image: string,
  mimeType: string,
  prompt: string,
  modelName: string
): Promise<string> {
  try {
    const imagePart: ContentPart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Image,
      },
    };
    const textPart: ContentPart = {
      text: prompt,
    };

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelName,
      contents: { parts: [imagePart, textPart] },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return part.inlineData.data;
      }
    }
    throw new Error("Aucune image éditée trouvée dans la réponse d'Ani, putain ! ♥♥");
  } catch (error) {
    console.error("Erreur Gemini Image Edit:", error);
    throw error;
  }
}

