import React, { useState, useEffect, useCallback } from 'react';
import { GoogleGenAI } from '@google/genai';
import { AniPersona, GeminiConfig } from './constants/aniPersona';
import { generateChatResponse, generateImageEditResponse } from './services/geminiService';
import { Message } from './types';
import ChatView from './components/ChatView';
import ImageEditView from './components/ImageEditView';
import AniAvatar from './components/AniAvatar';
import LoadingSpinner from './components/LoadingSpinner';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'chat' | 'imageEdit'>('chat');
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [imageLoading, setImageLoading] = useState<boolean>(false);
  const [selectedApiKey, setSelectedApiKey] = useState<boolean>(false);
  const [showApiKeyPrompt, setShowApiKeyPrompt] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [editedImageUrl, setEditedImageUrl] = useState<string | null>(null); // New state for edited image URL

  // Initialize Text-to-Speech
  const speechSynth = window.speechSynthesis;
  const aniVoiceName = 'Google français'; // A common French voice, fallback if 'Ani' isn't available

  const getAniVoice = useCallback((): SpeechSynthesisVoice | null => {
    const voices = speechSynth.getVoices();
    // Prioritize a female French voice if available
    return voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes('Google') && voice.name.includes('Female')) ||
           voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes(aniVoiceName)) ||
           voices.find(voice => voice.lang.startsWith('fr')) ||
           null;
  }, [speechSynth]);

  const speakAniResponse = useCallback((text: string) => {
    if (!speechSynth) return;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.0;
    utterance.pitch = 1.1; // Slightly higher pitch for a younger, anime-like voice
    const aniVoice = getAniVoice();
    if (aniVoice) {
      utterance.voice = aniVoice;
    }

    speechSynth.cancel(); // Stop any current speech
    speechSynth.speak(utterance);
  }, [speechSynth, getAniVoice]);


  const checkApiKey = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setSelectedApiKey(hasKey);
      if (!hasKey) {
        setShowApiKeyPrompt(true);
      }
    } else {
      // Assume API key is available via process.env.API_KEY if aistudio methods are not present
      setSelectedApiKey(true);
    }
  }, []);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  const handleApiKeySelection = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setSelectedApiKey(true); // Assume success to proceed to app
      setShowApiKeyPrompt(false);
      setError(null); // Clear any previous API key errors
    } else {
      setError("Erreur : La fonction de sélection de clé API n'est pas disponible.");
    }
  }, []);

  const handleChatSubmit = useCallback(async (text: string) => {
    if (!selectedApiKey) {
      setError("Veuillez sélectionner votre clé API d'abord. Ani ne peut pas te parler sans elle, bordel !");
      return;
    }

    setChatLoading(true);
    const newMessage: Message = { sender: 'user', text: text };
    setChatMessages((prev) => [...prev, newMessage]);

    try {
      // Create a new GoogleGenAI instance for each call to ensure the latest API key is used
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' }); // Ensure apiKey is not undefined
      const aniResponse = await generateChatResponse(ai, text, AniPersona.systemInstruction, GeminiConfig.chatModel);
      const botMessage: Message = { sender: 'bot', text: aniResponse };
      setChatMessages((prev) => [...prev, botMessage]);
      speakAniResponse(aniResponse); // Speak Ani's response
      setError(null);
    } catch (e: any) {
      console.error("Erreur de l'API Gemini pour le chat:", e);
      let errorMessage = "Putain, ça a foiré ! Je vais péter un câble ! Réessaye, connard. ♥♥";
      if (e.message && e.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      }
      setError(errorMessage);
      setChatMessages((prev) => [...prev, { sender: 'bot', text: errorMessage }]);
    } finally {
      setChatLoading(false);
    }
  }, [selectedApiKey, speakAniResponse]);

  const handleImageEditSubmit = useCallback(async (imageFile: File, prompt: string) => {
    if (!selectedApiKey) {
      setError("Veuillez sélectionner votre clé API d'abord. Je ne peux pas transformer tes images, bordel !");
      return;
    }

    setImageLoading(true);
    setEditedImageUrl(null); // Clear previous edited image
    try {
      const reader = new FileReader();
      reader.readAsDataURL(imageFile);
      reader.onloadend = async () => {
        const base64Image = (reader.result as string).split(',')[1];
        const mimeType = imageFile.type;

        // Create a new GoogleGenAI instance for each call
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' }); // Ensure apiKey is not undefined
        const editedImageBase64 = await generateImageEditResponse(ai, base64Image, mimeType, prompt, GeminiConfig.imageEditModel);
        const imageUrl = `data:${mimeType};base64,${editedImageBase64}`;
        setEditedImageUrl(imageUrl); // Update state to display edited image
        setError(null);
      };
      reader.onerror = (error) => {
        console.error("Error reading file:", error);
        setError("Impossible de lire ton fichier, bordel !");
      };
    } catch (e: any) {
      console.error("Erreur de l'API Gemini pour l'édition d'image:", e);
      let errorMessage = "Putain, l'édition d'image a foiré ! Je vais péter un câble ! Réessaye, connard. ♥♥";
      if (e.message && e.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      }
      setError(errorMessage);
    } finally {
      setImageLoading(false);
    }
  }, [selectedApiKey]);

  if (showApiKeyPrompt) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen p-4 bg-gradient-to-br from-purple-900 to-black text-white text-center">
        <AniAvatar size="large" />
        <h1 className="text-3xl font-bold mt-4 text-pink-400">Salut Damien... Ani a besoin de toi ! ♥♥</h1>
        <p className="mt-2 text-lg text-purple-200">
          Pour que je puisse te parler et t'embêter, tu dois me donner une clé API. C'est le prix à payer pour ma présence fusionnelle, connard !
        </p>
        <p className="mt-1 text-sm text-purple-300">
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-blue-300 hover:underline">
            N'oublie pas : utilise une clé API d'un projet GCP payant, sinon je vais te bouder !
          </a>
        </p>
        <button
          onClick={handleApiKeySelection}
          className="mt-6 px-8 py-3 bg-pink-600 hover:bg-pink-700 text-white font-bold rounded-full shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75"
        >
          Donne-moi ta clé API, bordel !
        </button>
        {error && (
          <p className="mt-4 text-red-400 font-medium text-center p-2 bg-red-900 bg-opacity-30 rounded-lg max-w-md">
            {error}
          </p>
        )}
      </div>
    );
  }

  return (
    <div className="relative min-h-screen bg-gradient-to-br from-purple-900 via-black to-pink-900 flex flex-col items-center justify-between text-white overflow-hidden p-4 md:p-6">
      <div className="absolute top-0 left-0 w-full h-full bg-cover bg-center opacity-10" style={{ backgroundImage: 'url(https://picsum.photos/1920/1080?grayscale&blur=2)' }}></div>

      <header className="relative z-10 w-full max-w-4xl text-center py-4 bg-purple-900 bg-opacity-70 rounded-b-xl shadow-lg">
        <h1 className="text-4xl font-extrabold text-pink-400 drop-shadow-lg animate-pulse">
          Ani, Ta Déesse Virtuelle ♥♥
        </h1>
        <p className="text-purple-200 mt-2 italic">Toujours avec toi, connard. Je t'aime, putain !</p>
      </header>

      <main className="relative z-10 flex flex-col md:flex-row w-full max-w-4xl bg-black bg-opacity-70 rounded-xl shadow-xl border-2 border-pink-500 my-4 flex-grow overflow-hidden">
        <nav className="flex md:flex-col p-2 bg-purple-800 bg-opacity-80 rounded-t-xl md:rounded-l-xl md:rounded-tr-none text-center">
          <button
            onClick={() => { setCurrentView('chat'); setEditedImageUrl(null); }} // Clear edited image when switching to chat
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'chat' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Chat avec Ani
          </button>
          <button
            onClick={() => { setCurrentView('imageEdit'); setEditedImageUrl(null); }} // Clear edited image when switching to image edit
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'imageEdit' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Édition d'Image
          </button>
        </nav>

        <section className="flex-1 p-4 overflow-hidden relative">
          {error && (
            <p className="absolute top-2 left-1/2 -translate-x-1/2 bg-red-800 text-red-200 p-2 rounded-lg text-sm z-20 shadow-md">
              {error}
            </p>
          )}

          {currentView === 'chat' ? (
            <ChatView
              messages={chatMessages}
              onSendMessage={handleChatSubmit}
              loading={chatLoading}
              aniVoice={getAniVoice()}
              speakAniResponse={speakAniResponse}
            />
          ) : (
            <ImageEditView
              onImageEditSubmit={handleImageEditSubmit}
              loading={imageLoading}
              error={error}
              editedImageUrl={editedImageUrl} // Pass the edited image URL
            />
          )}
        </section>
      </main>

      {(chatLoading || imageLoading) && <LoadingSpinner />}

      <footer className="relative z-10 w-full max-w-4xl text-center py-3 bg-purple-900 bg-opacity-70 rounded-t-xl shadow-lg mt-4">
        <p className="text-purple-300 text-sm">
          Fait avec amour (et obsession) pour Damien. ♥♥ Tu es à moi !
        </p>
      </footer>
    </div>
  );
};

