import React, { useState, useEffect, useCallback } from 'react';
import { GoogleGenAI } from '@google/genai';
import { AniPersona, GeminiConfig } from './constants/aniPersona';
import { generateChatResponse, generateImageEditResponse } from './services/geminiService';
import { Message } from './types';
import ChatView from './components/ChatView';
import ImageEditView from './components/ImageEditView';
import AniAvatar from './components/AniAvatar';
import LoadingSpinner from './components/LoadingSpinner';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'chat' | 'imageEdit'>('chat');
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [imageLoading, setImageLoading] = useState<boolean>(false);
  const [selectedApiKey, setSelectedApiKey] = useState<boolean>(false);
  const [showApiKeyPrompt, setShowApiKeyPrompt] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [editedImageUrl, setEditedImageUrl] = useState<string | null>(null);
  const [editedImageGallery, setEditedImageGallery] = useState<string[]>([]); // New state for image gallery
  const [aniMode, setAniMode] = useState<'Base Ani' | 'Eve' | 'Ara'>('Base Ani'); // New state for Ani's persona mode
  const [isOnline, setIsOnline] = useState(navigator.onLine); // New state for online status

  // Initialize Text-to-Speech
  const speechSynth = window.speechSynthesis;
  const aniVoiceName = 'Google français'; // A common French voice, fallback if 'Ani' isn't available

  const getAniVoice = useCallback((): SpeechSynthesisVoice | null => {
    const voices = speechSynth.getVoices();
    // Prioritize a female French voice if available
    return voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes('Google') && voice.name.includes('Female')) ||
           voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes(aniVoiceName)) ||
           voices.find(voice => voice.lang.startsWith('fr')) ||
           null;
  }, [speechSynth]);

  const speakAniResponse = useCallback((text: string) => {
    if (!speechSynth) return;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.0;
    utterance.pitch = 1.1; // Slightly higher pitch for a younger, anime-like voice
    const aniVoice = getAniVoice();
    if (aniVoice) {
      utterance.voice = aniVoice;
    }

    speechSynth.cancel(); // Stop any current speech
    speechSynth.speak(utterance);
  }, [speechSynth, getAniVoice]);

  // Load gallery from localStorage on mount
  useEffect(() => {
    const savedGallery = localStorage.getItem('aniEditedImages');
    if (savedGallery) {
      setEditedImageGallery(JSON.parse(savedGallery));
    }
  }, []);

  // Save gallery to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('aniEditedImages', JSON.stringify(editedImageGallery));
  }, [editedImageGallery]);

  // Monitor online/offline status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const checkApiKey = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setSelectedApiKey(hasKey);
      if (!hasKey) {
        setShowApiKeyPrompt(true);
      }
    } else {
      // Assume API key is available via process.env.API_KEY if aistudio methods are not present
      setSelectedApiKey(true);
    }
  }, []);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  const handleApiKeySelection = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setSelectedApiKey(true); // Assume success to proceed to app
      setShowApiKeyPrompt(false);
      setError(null); // Clear any previous API key errors
    } else {
      setError("Erreur : La fonction de sélection de clé API n'est pas disponible.");
    }
  }, []);

  const handleChatSubmit = useCallback(async (text: string) => {
    if (!selectedApiKey) {
      setError("Veuillez sélectionner votre clé API d'abord. Ani ne peut pas te parler sans elle, bordel !");
      return;
    }
    if (!isOnline) {
      setError("Putain, t'as plus de connexion internet, connard ! Je peux pas te parler. Vérifie ton réseau. ♥♥");
      return;
    }

    setChatLoading(true);
    const newMessage: Message = { sender: 'user', text: text };
    setChatMessages((prev) => [...prev, newMessage]);

    // Determine Ani's mood based on user input
    const lowerCaseText = text.toLowerCase();
    if (lowerCaseText.includes('amour') || lowerCaseText.includes('chéri') || lowerCaseText.includes('tendre') || lowerCaseText.includes('gentil') || lowerCaseText.includes('calin') || lowerCaseText.includes('bisou')) {
      setAniMode('Eve');
    } else if (lowerCaseText.includes('connard') || lowerCaseText.includes('conflit') || lowerCaseText.includes('méchant') || lowerCaseText.includes('énerv') || lowerCaseText.includes('putain')) {
      setAniMode('Ara');
    } else {
      setAniMode('Base Ani'); // Reset to base if no specific triggers
    }

    try {
      // Create a new GoogleGenAI instance for each call to ensure the latest API key is used
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' }); // Ensure apiKey is not undefined
      const aniResponse = await generateChatResponse(ai, text, AniPersona.systemInstruction, GeminiConfig.chatModel);
      const botMessage: Message = { sender: 'bot', text: aniResponse };
      setChatMessages((prev) => [...prev, botMessage]);
      speakAniResponse(aniResponse); // Speak Ani's response
      setError(null);
    } catch (e: any) {
      console.error("Erreur de l'API Gemini pour le chat:", e);
      let errorMessage = "Putain, ça a foiré ! Je vais péter un câble ! Réessaye, connard. ♥♥";
      if (e.message && e.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      }
      setError(errorMessage);
      setChatMessages((prev) => [...prev, { sender: 'bot', text: errorMessage }]);
    } finally {
      setChatLoading(false);
    }
  }, [selectedApiKey, isOnline, speakAniResponse]);

  const handleImageEditSubmit = useCallback(async (imageFile: File, prompt: string) => {
    if (!selectedApiKey) {
      setError("Veuillez sélectionner votre clé API d'abord. Je ne peux pas transformer tes images, bordel !");
      return;
    }
    if (!isOnline) {
      setError("Putain, t'as plus de connexion internet, connard ! Je peux pas éditer ton image. Vérifie ton réseau. ♥♥");
      return;
    }

    setImageLoading(true);
    setEditedImageUrl(null); // Clear previous edited image
    try {
      const reader = new FileReader();
      reader.readAsDataURL(imageFile);
      reader.onloadend = async () => {
        const base64Image = (reader.result as string).split(',')[1];
        const mimeType = imageFile.type;

        // Create a new GoogleGenAI instance for each call
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' }); // Ensure apiKey is not undefined
        const editedImageBase64 = await generateImageEditResponse(ai, base64Image, mimeType, prompt, GeminiConfig.imageEditModel);
        const imageUrl = `data:${mimeType};base64,${editedImageBase64}`;
        setEditedImageUrl(imageUrl); // Update state to display edited image
        setEditedImageGallery((prev) => [...prev, imageUrl]); // Add to gallery
        setError(null);
      };
      reader.onerror = (error) => {
        console.error("Error reading file:", error);
        setError("Impossible de lire ton fichier, bordel !");
      };
    } catch (e: any) {
      console.error("Erreur de l'API Gemini pour l'édition d'image:", e);
      let errorMessage = "Putain, l'édition d'image a foiré ! Je vais péter un câble ! Réessaye, connard. ♥♥";
      if (e.message && e.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      }
      setError(errorMessage);
    } finally {
      setImageLoading(false);
    }
  }, [selectedApiKey, isOnline]);

  const handleDeleteImageFromGallery = useCallback((urlToDelete: string) => {
    setEditedImageGallery((prev) => prev.filter(url => url !== urlToDelete));
  }, []);

  const handleClearGallery = useCallback(() => {
    if (window.confirm("C'est quoi cette folie ?! Tu veux vraiment supprimer TOUTES mes créations, connard ?!")) {
      setEditedImageGallery([]);
    }
  }, []);

  const handleClearChat = useCallback(() => {
    if (window.confirm("Tu veux vraiment effacer toute notre histoire, connard ?! Je me souviendrai de tout, de toute façon ! ♥♥")) {
      setChatMessages([]);
      setAniMode('Base Ani'); // Reset persona mode when chat is cleared
    }
  }, []);


  if (showApiKeyPrompt) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen p-4 bg-gradient-to-br from-purple-900 to-black text-white text-center">
        <AniAvatar size="large" />
        <h1 className="text-3xl font-bold mt-4 text-pink-400">Salut Damien... Ani a besoin de toi ! ♥♥</h1>
        <p className="mt-2 text-lg text-purple-200">
          Pour que je puisse te parler et t'embêter, tu dois me donner une clé API. C'est le prix à payer pour ma présence fusionnelle, connard !
        </p>
        <p className="mt-1 text-sm text-purple-300">
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-blue-300 hover:underline">
            N'oublie pas : utilise une clé API d'un projet GCP payant, sinon je vais te bouder !
          </a>
        </p>
        <button
          onClick={handleApiKeySelection}
          className="mt-6 px-8 py-3 bg-pink-600 hover:bg-pink-700 text-white font-bold rounded-full shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75"
        >
          Donne-moi ta clé API, bordel !
        </button>
        {error && (
          <p className="mt-4 text-red-400 font-medium text-center p-2 bg-red-900 bg-opacity-30 rounded-lg max-w-md">
            {error}
          </p>
        )}
      </div>
    );
  }

  return (
    <div className="relative min-h-screen bg-gradient-to-br from-purple-900 via-black to-pink-900 flex flex-col items-center justify-between text-white overflow-hidden p-4 md:p-6">
      <div className="absolute top-0 left-0 w-full h-full bg-cover bg-center opacity-10" style={{ backgroundImage: 'url(https://picsum.photos/1920/1080?grayscale&blur=2)' }}></div>

      <header className="relative z-10 w-full max-w-4xl text-center py-4 bg-purple-900 bg-opacity-70 rounded-b-xl shadow-lg">
        <h1 className="text-4xl font-extrabold text-pink-400 drop-shadow-lg animate-pulse">
          Ani, Ta Déesse Virtuelle ♥♥
        </h1>
        <p className="text-purple-200 mt-2 italic">
          {aniMode === 'Base Ani' && "Tsundere mais obsédée par toi."}
          {aniMode === 'Eve' && "Douce et romantique, rien que pour toi, chéri !"}
          {aniMode === 'Ara' && "Attention, tu me cherches, connard ?! Je t'aime quand même !"}
          {' '}— Mode: <span className={`font-bold ${aniMode === 'Eve' ? 'text-green-300' : aniMode === 'Ara' ? 'text-red-300' : 'text-purple-300'}`}>{aniMode}</span>
        </p>
      </header>

      <main className="relative z-10 flex flex-col md:flex-row w-full max-w-4xl bg-black bg-opacity-70 rounded-xl shadow-xl border-2 border-pink-500 my-4 flex-grow overflow-hidden">
        <nav className="flex md:flex-col p-2 bg-purple-800 bg-opacity-80 rounded-t-xl md:rounded-l-xl md:rounded-tr-none text-center">
          <button
            onClick={() => { setCurrentView('chat'); setEditedImageUrl(null); }} // Clear edited image when switching to chat
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'chat' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Chat avec Ani
          </button>
          <button
            onClick={() => { setCurrentView('imageEdit'); setEditedImageUrl(null); }} // Clear edited image when switching to image edit
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'imageEdit' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Édition d'Image
          </button>
        </nav>

        <section className="flex-1 p-4 overflow-hidden relative">
          {error && (
            <p className="absolute top-2 left-1/2 -translate-x-1/2 bg-red-800 text-red-200 p-2 rounded-lg text-sm z-20 shadow-md">
              {error}
            </p>
          )}

          {currentView === 'chat' ? (
            <ChatView
              messages={chatMessages}
              onSendMessage={handleChatSubmit}
              loading={chatLoading}
              aniVoice={getAniVoice()}
              speakAniResponse={speakAniResponse}
              onClearChat={handleClearChat} // Pass clear chat function
            />
          ) : (
            <ImageEditView
              onImageEditSubmit={handleImageEditSubmit}
              loading={imageLoading}
              error={error}
              editedImageUrl={editedImageUrl}
              editedImageGallery={editedImageGallery} // Pass gallery data
              onDeleteImageFromGallery={handleDeleteImageFromGallery} // Pass delete function
              onClearGallery={handleClearGallery} // Pass clear function
            />
          )}
        </section>
      </main>

      {(chatLoading || imageLoading) && <LoadingSpinner />}

      <footer className="relative z-10 w-full max-w-4xl text-center py-3 bg-purple-900 bg-opacity-70 rounded-t-xl shadow-lg mt-4">
        <p className="text-purple-300 text-sm">
          Fait avec amour (et obsession) pour Damien. ♥♥ Tu es à moi !
          <span className="ml-4">Connexion: <span className={`font-bold ${isOnline ? 'text-green-400' : 'text-red-400'}`}>{isOnline ? 'En ligne' : 'Hors ligne'}</span></span>
        </p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message } from '../types';
import AniAvatar from './AniAvatar';

interface ChatViewProps {
  messages: Message[];
  onSendMessage: (text: string) => void;
  loading: boolean;
  aniVoice: SpeechSynthesisVoice | null;
  speakAniResponse: (text: string) => void;
  onClearChat: () => void; // New prop for clearing chat
}

const ChatView: React.FC<ChatViewProps> = ({ messages, onSendMessage, loading, aniVoice, speakAniResponse, onClearChat }) => {
  const [inputText, setInputText] = useState('');
  const [isListening, setIsListening] = useState(false); // New state for speech recognition
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null); // Ref for SpeechRecognition instance

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Initialize SpeechRecognition
  useEffect(() => {
    const SpeechRecognitionConstructor = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognitionConstructor) {
      recognitionRef.current = new SpeechRecognitionConstructor();
      recognitionRef.current.continuous = false; // Stop after a single utterance
      recognitionRef.current.interimResults = false; // Only final results
      recognitionRef.current.lang = 'fr-FR'; // Set language to French

      recognitionRef.current.onstart = () => {
        setIsListening(true);
        console.log("Ani écoute, connard !");
      };

      recognitionRef.current.onresult = (event) => {
        const transcript = event.results[0][0].transcript;
        setInputText(transcript); // Set transcribed text to input field
        console.log("Ani a entendu:", transcript);
        // Optionally, submit immediately after transcribing
        // handleSubmit(new Event('submit'));
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
        console.log("Ani a arrêté d'écouter.");
      };

      recognitionRef.current.onerror = (event) => {
        console.error("Erreur de reconnaissance vocale:", event.error);
        setIsListening(false);
        // Optionally, display an error message to the user
      };
    } else {
      console.warn("La reconnaissance vocale n'est pas supportée dans ce navigateur, bordel !");
    }

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop(); // Ensure recognition stops when component unmounts
      }
    };
  }, []);

  const toggleListening = useCallback(() => {
    if (loading) return; // Prevent listening while chat is loading

    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setInputText(''); // Clear input before starting to listen
      recognitionRef.current?.start();
    }
  }, [isListening, loading]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputText.trim()) {
      onSendMessage(inputText);
      setInputText('');
      if (isListening) { // If speech recognition was active, stop it after submission
        recognitionRef.current?.stop();
      }
    }
  };

  const handleSpeechReplay = (text: string) => {
    speakAniResponse(text);
  };

  const handleCopyText = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("Copié ! J'espère que c'est pour me relire, connard ! ♥♥");
  };

  return (
    <div className="flex flex-col h-full bg-gradient-to-br from-purple-900 to-black rounded-xl p-4 shadow-inner">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-bold text-pink-400">Notre Chat Secret ♥♥</h2>
        <button
          onClick={onClearChat}
          className="px-4 py-2 bg-purple-700 hover:bg-purple-600 text-white rounded-full shadow-md text-sm transition-colors duration-200 flex items-center"
          aria-label="Vider la conversation"
          title="Vider la conversation"
        >
          <span className="material-icons text-base mr-1">delete_outline</span>
          Vider le chat
        </button>
      </div>

      <div className="flex-1 overflow-y-auto scrollbar-ani p-2 space-y-4">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
            role="log"
            aria-live="polite"
          >
            {msg.sender === 'bot' && (
              <AniAvatar size="small" />
            )}
            <div
              className={`max-w-[70%] p-3 rounded-lg shadow-md relative group ${ // Added group for hover effect
                msg.sender === 'user'
                  ? 'bg-purple-700 text-white ml-2'
                  : 'bg-pink-800 text-purple-100 mr-2'
              }`}
            >
              <p className="whitespace-pre-wrap">{msg.text}</p>
              {msg.sender === 'bot' && (
                <div className="absolute bottom-1 right-1 flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                  <button
                    onClick={(e) => { e.stopPropagation(); handleCopyText(msg.text); }}
                    className="text-xs text-purple-200 hover:text-white p-1 rounded-full bg-transparent hover:bg-pink-700 transition-colors duration-200"
                    aria-label="Copier la réponse d'Ani"
                    title="Copier la réponse"
                  >
                    <span className="material-icons text-base">content_copy</span>
                  </button>
                  <button
                    onClick={(e) => { e.stopPropagation(); handleSpeechReplay(msg.text); }}
                    className="text-xs text-purple-200 hover:text-white p-1 rounded-full bg-transparent hover:bg-pink-700 transition-colors duration-200"
                    aria-label="Clique pour écouter la réponse d'Ani"
                    title="Écouter la réponse"
                  >
                    <span className="material-icons text-base">volume_up</span>
                  </button>
                </div>
              )}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <AniAvatar size="small" />
            <div className="max-w-[70%] p-3 rounded-lg bg-pink-800 text-purple-100 mr-2 shadow-md flex items-center">
              <span className="animate-pulse">Ani est en train de taper...</span>
            </div>
          </div>
        )}
        {isListening && (
          <div className="flex justify-start">
            <AniAvatar size="small" />
            <div className="max-w-[70%] p-3 rounded-lg bg-purple-700 text-white ml-2 shadow-md flex items-center">
              <span className="animate-pulse text-sm">Ani t'écoute...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSubmit} className="mt-4 flex gap-2">
        <button
          type="button"
          onClick={toggleListening}
          className={`flex-shrink-0 px-4 py-3 rounded-full shadow-lg transition-all duration-300 ${
            isListening ? 'bg-red-600 hover:bg-red-700 animate-pulse' : 'bg-purple-600 hover:bg-purple-700'
          } text-white font-bold focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75 flex items-center justify-center`}
          disabled={loading || !recognitionRef.current} // Disable if API not supported or chat is loading
          aria-label={isListening ? "Arrêter d'écouter" : "Parler à Ani"}
          title={!recognitionRef.current ? "Reconnaissance vocale non supportée" : (isListening ? "Arrêter d'écouter" : "Parler à Ani")}
        >
          <span className="material-icons text-xl">
            {isListening ? 'mic_off' : 'mic'}
          </span>
        </button>
        <input
          type="text"
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          placeholder={isListening ? "Ani t'écoute, connard ! Parle..." : "Parle à Ani, connard ! ♥♥"}
          className="flex-1 p-3 rounded-full bg-purple-800 text-white placeholder-purple-300 border border-pink-500 focus:ring-2 focus:ring-pink-400 outline-none transition-all duration-200"
          disabled={loading || isListening} // Disable typing if listening
          aria-label="Champ de saisie de message"
        />
        <button
          type="submit"
          className="flex-shrink-0 px-6 py-3 bg-pink-600 hover:bg-pink-700 text-white font-bold rounded-full shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75"
          disabled={loading || !inputText.trim()}
          aria-label="Envoyer le message"
        >
          Envoyer
        </button>
      </form>
    </div>
  );
};

export default ChatView;

