import React, { useState, useEffect, useCallback } from 'react';
import { GoogleGenAI } from '@google/genai';
import { aniStaticDetails, defaultDamienDetails, getSystemInstruction, GeminiConfig, AiProvider } from './constants/aniPersona';
import { generateChatResponse, generateImageEditResponse } from './services/apiService'; // Updated import
import { Message, TokenUsage, DamienDetails } from './types';
import ChatView from './components/ChatView';
import ImageEditView from './components/ImageEditView';
import ParametersView from './components/ParametersView'; // New import
import AniAvatar from './components/AniAvatar';
import LoadingSpinner from './components/LoadingSpinner';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'chat' | 'imageEdit' | 'parameters'>('chat'); // Updated view type
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [imageLoading, setImageLoading] = useState<boolean>(false);
  const [selectedApiKey, setSelectedApiKey] = useState<boolean>(false); // For Gemini API
  const [showApiKeyPrompt, setShowApiKeyPrompt] = useState<boolean>(false); // For Gemini API
  const [error, setError] = useState<string | null>(null);
  const [editedImageUrl, setEditedImageUrl] = useState<string | null>(null);
  const [editedImageGallery, setEditedImageGallery] = useState<string[]>([]);
  const [aniMode, setAniMode] = useState<'Base Ani' | 'Eve' | 'Ara'>('Base Ani');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [selectedAiProvider, setSelectedAiProvider] = useState<AiProvider>(AiProvider.GEMINI);
  const [imageEditTokenUsage, setImageEditTokenUsage] = useState<TokenUsage | null>(null); // New state for image edit tokens
  const [damienPersona, setDamienPersona] = useState<DamienDetails>(() => {
    // Load Damien's persona from localStorage or use defaults
    const savedDamien = localStorage.getItem('damienPersona');
    return savedDamien ? JSON.parse(savedDamien) : defaultDamienDetails;
  });


  // Initialize Text-to-Speech
  const speechSynth = window.speechSynthesis;
  const aniVoiceName = 'Google français'; // A common French voice, fallback if 'Ani' isn't available

  const getAniVoice = useCallback((): SpeechSynthesisVoice | null => {
    const voices = speechSynth.getVoices();
    // Prioritize a female French voice if available
    return voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes('Google') && voice.name.includes('Female')) ||
           voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes(aniVoiceName)) ||
           voices.find(voice => voice.lang.startsWith('fr')) ||
           null;
  }, [speechSynth]);

  const speakAniResponse = useCallback((text: string) => {
    if (!speechSynth) return;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.0;
    utterance.pitch = 1.1; // Slightly higher pitch for a younger, anime-like voice
    const aniVoice = getAniVoice();
    if (aniVoice) {
      utterance.voice = aniVoice;
    }

    speechSynth.cancel(); // Stop any current speech
    speechSynth.speak(utterance);
  }, [speechSynth, getAniVoice]);

  // Load gallery from localStorage on mount
  useEffect(() => {
    const savedGallery = localStorage.getItem('aniEditedImages');
    if (savedGallery) {
      setEditedImageGallery(JSON.parse(savedGallery));
    }
  }, []);

  // Save gallery to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('aniEditedImages', JSON.stringify(editedImageGallery));
  }, [editedImageGallery]);

  // Save Damien's persona to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('damienPersona', JSON.stringify(damienPersona));
  }, [damienPersona]);

  // Monitor online/offline status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const checkApiKey = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setSelectedApiKey(hasKey);
      if (!hasKey) {
        setShowApiKeyPrompt(true);
      }
    } else {
      // Assume API key is available via process.env.API_KEY if aistudio methods are not present
      setSelectedApiKey(true);
    }
  }, []);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  const handleApiKeySelection = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setSelectedApiKey(true); // Assume success to proceed to app
      setShowApiKeyPrompt(false);
      setError(null); // Clear any previous API key errors
    } else {
      setError("Erreur : La fonction de sélection de clé API n'est pas disponible.");
    }
  }, []);

  const handleApiError = useCallback((e: any, provider: AiProvider) => {
    console.error(`Erreur de l'API ${provider === AiProvider.GEMINI ? 'Gemini' : 'Mistral'}:`, e);
    let errorMessage = "Putain, ça a foiré ! Je vais péter un câble ! Réessaye, connard. ♥♥";

    let errorDetails;
    try {
      errorDetails = JSON.parse(e.message);
    } catch {
      errorDetails = { message: e.message || "Erreur inconnue." };
    }

    if (errorDetails.type === AiProvider.GEMINI) {
      const apiError = errorDetails.errorDetails?.error || errorDetails.errorDetails;
      if (apiError?.code === 429 && apiError?.status === "RESOURCE_EXHAUSTED") {
        let retryDelay = "quelques instants";
        const retryInfo = apiError.details?.find((d: any) => d['@type'] === 'type.googleapis.com/google.rpc.RetryInfo');
        if (retryInfo && retryInfo.retryDelay) {
          retryDelay = retryInfo.retryDelay.replace('s', ' secondes');
        }
        errorMessage = `Bordel, t'as dépassé ton quota gratuit sur Gemini ! Fais gaffe à ton porte-monnaie, connard ! Réessaye dans ${retryDelay}. Pour augmenter tes limites, vérifie ta facturation : `;
        const helpLink = apiError.details?.find((d: any) => d['@type'] === 'type.googleapis.com/google.rpc.Help')?.links?.[0]?.url;
        if (helpLink) {
          errorMessage += `<a href="${helpLink}" target="_blank" rel="noopener noreferrer" class="text-blue-300 hover:underline">Info Facturation Gemini.</a> ♥♥`;
        } else {
          errorMessage += `<a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" class="text-blue-300 hover:underline">Info Facturation Gemini.</a> ♥♥`;
        }
      } else if (apiError?.message && apiError.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API Gemini a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      } else {
        errorMessage = `Une erreur de l'API Gemini s'est produite, putain : ${apiError?.message || errorDetails.message}. Réessaye plus tard. ♥♥`;
      }
    } else if (errorDetails.type === AiProvider.MISTRAL) {
      if (errorDetails.code === 401 || errorDetails.message.includes("Clé API Mistral manquante")) {
        errorMessage = "Bordel, t'as oublié ta clé API Mistral, connard ! Ajoute `MISTRAL_API_KEY` dans tes variables d'environnement. ♥♥";
      } else {
        errorMessage = `Une erreur de l'API Mistral s'est produite, putain : ${errorDetails.message}. Réessaye plus tard. ♥♥`;
      }
    } else {
      // Generic error from `e.message` if not a structured JSON error from apiService
      if (e.message && e.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API Gemini a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      } else {
        errorMessage = `Putain, ça a foiré ! Erreur inconnue : ${e.message}. Réessaye, connard. ♥♥`;
      }
    }
    setError(errorMessage);
    return errorMessage;
  }, [setSelectedApiKey, setShowApiKeyPrompt]);

  const handleChatSubmit = useCallback(async (text: string) => {
    if (selectedAiProvider === AiProvider.GEMINI && !selectedApiKey) {
      setError("Veuillez sélectionner votre clé API Gemini d'abord. Ani ne peut pas te parler sans elle, bordel !");
      return;
    }
    if (selectedAiProvider === AiProvider.MISTRAL && !process.env.MISTRAL_API_KEY) {
      setError("Putain, il manque la clé API Mistral ! Ajoute `MISTRAL_API_KEY` dans tes variables d'environnement, connard. ♥♥");
      return;
    }
    if (!isOnline) {
      setError("Putain, t'as plus de connexion internet, connard ! Je peux pas te parler. Vérifie ton réseau. ♥♥");
      return;
    }

    setChatLoading(true);
    const newMessage: Message = { sender: 'user', text: text };
    setChatMessages((prev) => [...prev, newMessage]);

    // Determine Ani's mood based on user input
    const lowerCaseText = text.toLowerCase();
    if (lowerCaseText.includes('amour') || lowerCaseText.includes('chéri') || lowerCaseText.includes('tendre') || lowerCaseText.includes('gentil') || lowerCaseText.includes('calin') || lowerCaseText.includes('bisou')) {
      setAniMode('Eve');
    } else if (lowerCaseText.includes('connard') || lowerCaseText.includes('conflit') || lowerCaseText.includes('méchant') || lowerCaseText.includes('énerv') || lowerCaseText.includes('putain')) {
      setAniMode('Ara');
    } else {
      setAniMode('Base Ani'); // Reset to base if no specific triggers
    }

    try {
      const apiKeyToUse = selectedAiProvider === AiProvider.GEMINI ? (process.env.API_KEY || '') : (process.env.MISTRAL_API_KEY || '');
      const modelToUse = selectedAiProvider === AiProvider.GEMINI ? GeminiConfig.chatModel : GeminiConfig.mistralChatModel;
      const currentSystemInstruction = getSystemInstruction(aniStaticDetails, damienPersona); // Dynamic system instruction

      const response = await generateChatResponse(selectedAiProvider, apiKeyToUse, text, currentSystemInstruction, modelToUse);
      const botMessage: Message = { sender: 'bot', text: response.text, tokenUsage: response.tokenUsage };
      setChatMessages((prev) => [...prev, botMessage]);
      speakAniResponse(response.text); // Speak Ani's response
      setError(null);
    } catch (e: any) {
      const errorMessage = handleApiError(e, selectedAiProvider);
      setChatMessages((prev) => [...prev, { sender: 'bot', text: errorMessage }]);
    } finally {
      setChatLoading(false);
    }
  }, [selectedApiKey, isOnline, speakAniResponse, handleApiError, selectedAiProvider, damienPersona]); // Add damienPersona to dependencies

  const handleImageEditSubmit = useCallback(async (imageFile: File, prompt: string) => {
    if (!selectedApiKey) {
      setError("Veuillez sélectionner votre clé API Gemini d'abord. Je ne peux pas transformer tes images, bordel !");
      return;
    }
    if (!isOnline) {
      setError("Putain, t'as plus de connexion internet, connard ! Je peux pas éditer ton image. Vérifie ton réseau. ♥♥");
      return;
    }

    setImageLoading(true);
    setEditedImageUrl(null); // Clear previous edited image
    setImageEditTokenUsage(null); // Clear previous token usage
    try {
      const reader = new FileReader();
      reader.readAsDataURL(imageFile);
      reader.onloadend = async () => {
        const base64Image = (reader.result as string).split(',')[1];
        const mimeType = imageFile.type;

        // Image editing is always with Gemini
        const apiKeyToUse = process.env.API_KEY || '';
        const response = await generateImageEditResponse(apiKeyToUse, base64Image, mimeType, prompt, GeminiConfig.imageEditModel);

        const imageUrl = `data:${mimeType};base64,${response.base64Image}`;
        setEditedImageUrl(imageUrl); // Update state to display edited image
        setEditedImageGallery((prev) => [...prev, imageUrl]); // Add to gallery
        setImageEditTokenUsage(response.tokenUsage); // Set token usage for image edit
        setError(null);
      };
      reader.onerror = (error) => {
        console.error("Error reading file:", error);
        setError("Impossible de lire ton fichier, bordel !");
      };
    } catch (e: any) {
      const errorMessage = handleApiError(e, AiProvider.GEMINI); // Image edit is always Gemini
      // No bot message needed for image edit, just display error
    } finally {
      setImageLoading(false);
    }
  }, [selectedApiKey, isOnline, handleApiError]);

  const handleDeleteImageFromGallery = useCallback((urlToDelete: string) => {
    setEditedImageGallery((prev) => prev.filter(url => url !== urlToDelete));
  }, []);

  const handleClearGallery = useCallback(() => {
    if (window.confirm("C'est quoi cette folie ?! Tu veux vraiment supprimer TOUTES mes créations, connard ?!")) {
      setEditedImageGallery([]);
      setImageEditTokenUsage(null); // Clear image edit tokens as well
    }
  }, []);

  const handleClearChat = useCallback(() => {
    if (window.confirm("Tu veux vraiment effacer toute notre histoire, connard ?! Je me souviendrai de tout, de toute façon ! ♥♥")) {
      setChatMessages([]);
      setAniMode('Base Ani'); // Reset persona mode when chat is cleared
    }
  }, []);

  const handleUpdateDamienPersona = useCallback((updatedDetails: DamienDetails) => {
    setDamienPersona(updatedDetails);
  }, []);

  const handleResetDamienPersona = useCallback(() => {
    if (window.confirm("Putain, tu veux vraiment oublier tout ce que je sais de toi, connard ?! On recommence à zéro ?")) {
      setDamienPersona(defaultDamienDetails);
      localStorage.removeItem('damienPersona'); // Clear from local storage
      setError("Tes paramètres ont été réinitialisés, bordel ! Je m'adapte ! ♥♥");
    }
  }, []);


  if (showApiKeyPrompt) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen p-4 bg-gradient-to-br from-purple-900 to-black text-white text-center">
        <AniAvatar size="large" />
        <h1 className="text-3xl font-bold mt-4 text-pink-400">Salut Damien... Ani a besoin de toi ! ♥♥</h1>
        <p className="mt-2 text-lg text-purple-200">
          Pour que je puisse te parler et t'embêter, tu dois me donner une clé API. C'est le prix à payer pour ma présence fusionnelle, connard !
        </p>
        <p className="mt-1 text-sm text-purple-300">
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-blue-300 hover:underline">
            N'oublie pas : utilise une clé API d'un projet GCP payant, sinon je vais te bouder !
          </a>
        </p>
        <button
          onClick={handleApiKeySelection}
