import LoadingSpinner from './components/LoadingSpinner';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'chat' | 'imageEdit' | 'parameters'>('chat'); // Updated view type
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [imageLoading, setImageLoading] = useState<boolean>(false);
  const [selectedApiKey, setSelectedApiKey] = useState<boolean>(false); // For Gemini API
  const [showApiKeyPrompt, setShowApiKeyPrompt] = useState<boolean>(false); // For Gemini API
  const [error, setError] = useState<string | null>(null);
  const [editedImageUrl, setEditedImageUrl] = useState<string | null>(null);
  const [editedImageGallery, setEditedImageGallery] = useState<string[]>([]);
  const [aniMode, setAniMode] = useState<'Base Ani' | 'Eve' | 'Ara'>('Base Ani');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [selectedAiProvider, setSelectedAiProvider] = useState<AiProvider>(AiProvider.GEMINI);
  const [imageEditTokenUsage, setImageEditTokenUsage] = useState<TokenUsage | null>(null); // New state for image edit tokens
  const [damienPersona, setDamienPersona] = useState<DamienDetails>(() => {
    // Load Damien's persona from localStorage or use defaults
    const savedDamien = localStorage.getItem('damienPersona');
    return savedDamien ? JSON.parse(savedDamien) : defaultDamienDetails;
  });


  // Initialize Text-to-Speech
  const speechSynth = window.speechSynthesis;
  const aniVoiceName = 'Google français'; // A common French voice, fallback if 'Ani' isn't available

  const getAniVoice = useCallback((): SpeechSynthesisVoice | null => {
    const voices = speechSynth.getVoices();
    // Prioritize a female French voice if available
    return voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes('Google') && voice.name.includes('Female')) ||
           voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes(aniVoiceName)) ||
           voices.find(voice => voice.lang.startsWith('fr')) ||
           null;
  }, [speechSynth]);

  const speakAniResponse = useCallback((text: string) => {
    if (!speechSynth) return;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.0;
    utterance.pitch = 1.1; // Slightly higher pitch for a younger, anime-like voice
    const aniVoice = getAniVoice();
    if (aniVoice) {
      utterance.voice = aniVoice;
    }

    speechSynth.cancel(); // Stop any current speech
    speechSynth.speak(utterance);
  }, [speechSynth, getAniVoice]);

  // Load gallery from localStorage on mount
  useEffect(() => {
    const savedGallery = localStorage.getItem('aniEditedImages');
    if (savedGallery) {
      setEditedImageGallery(JSON.parse(savedGallery));
    }
  }, []);

  // Save gallery to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('aniEditedImages', JSON.stringify(editedImageGallery));
  }, [editedImageGallery]);

  // Save Damien's persona to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('damienPersona', JSON.stringify(damienPersona));
  }, [damienPersona]);

  // Monitor online/offline status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const checkApiKey = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setSelectedApiKey(hasKey);
      if (!hasKey) {
        setShowApiKeyPrompt(true);
      }
    } else {
      // Assume API key is available via process.env.API_KEY if aistudio methods are not present
      setSelectedApiKey(true);
    }
  }, []);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  const handleApiKeySelection = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setSelectedApiKey(true); // Assume success to proceed to app
      setShowApiKeyPrompt(false);
      setError(null); // Clear any previous API key errors
    } else {
      setError("Erreur : La fonction de sélection de clé API n'est pas disponible.");
    }
  }, []);

