/**
 * Provides the resolved AI service configuration,
 * prioritizing UI overrides from `damienDetails`,
 * then environment variables, and finally default hardcoded values.
 */
export function getAiServiceConfig(damienDetails: DamienDetails) {
  return {
    // Gemini Configuration
    // IMPORTANT: Google Gemini API key MUST be obtained exclusively from process.env.API_KEY.
    // Do NOT hardcode this value or create UI elements for it.
    geminiApiKey: process.env.API_KEY || '', 
    geminiChatModel: 'gemini-3-flash-preview', // Basic Text Tasks
    geminiImageEditModel: 'gemini-2.5-flash-image', // General Image Generation and Editing Tasks

    // Mistral Configuration - Prioritize UI override > ENV > Default
    mistralApiKey: damienDetails.mistralApiKeyOverride || process.env.MISTRAL_API_KEY || 'YOUR_MISTRAL_API_KEY_HERE',
    mistralApiUrl: damienDetails.mistralApiUrlOverride || process.env.MISTRAL_API_URL || 'https://api.mistral.ai/v1/chat/completions',
    mistralChatModel: 'mistral-tiny', // Default Mistral model for chat
  };
}

export type ResolvedAiServiceConfig = ReturnType<typeof getAiServiceConfig>;


export enum AiProvider {
  GEMINI = 'gemini',
  MISTRAL = 'mistral',
}

import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { ContentPart, TokenUsage } from '../types';
import { AiProvider, getAiServiceConfig, ResolvedAiServiceConfig } from '../constants/aniPersona'; // Updated import to use getAiServiceConfig and ResolvedAiServiceConfig

interface ChatResponse {
  text: string;
  tokenUsage: TokenUsage;
}

interface ImageEditResponse {
  base64Image: string;
  tokenUsage: TokenUsage;
}

/**
 * Generates a chat response from the selected AI model (Gemini or Mistral).
 * @param provider The selected AI provider.
 * @param resolvedConfig The resolved AI service configuration.
 * @param prompt The user's message.
 * @param systemInstruction The system instruction for the chat.
 * @param modelName The name of the AI model to use for chat.
 * @returns The text response and token usage.
 */
export async function generateChatResponse(
  provider: AiProvider,
  resolvedConfig: ResolvedAiServiceConfig, // Now accepts the resolved config
  prompt: string,
  systemInstruction: string,
  modelName: string
): Promise<ChatResponse> {
  if (provider === AiProvider.GEMINI) {
    const geminiApiKey = resolvedConfig.geminiApiKey; // Get from resolved config
    if (!geminiApiKey) {
      // This case should ideally be caught by App.tsx's API key selection check
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
    }
    try {
      const ai = new GoogleGenAI({ apiKey: geminiApiKey });
      const chat = ai.chats.create({
        model: modelName, // This will be resolvedConfig.geminiChatModel
        config: {
          systemInstruction: systemInstruction,
        },
      });

      const response: GenerateContentResponse = await chat.sendMessage({ message: prompt });
      const text = response.text || "Ani est muette, c'est ouf ! ♥♥";
      const promptTokens = response.usageMetadata?.promptTokenCount || 0;
      const completionTokens = response.usageMetadata?.candidatesTokenCount || 0;
      const totalTokens = promptTokens + completionTokens;

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
      };
    } catch (error: any) {
      console.error("Erreur Gemini Chat:", error);
      throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
    }
  } else if (provider === AiProvider.MISTRAL) {
    const mistralApiKey = resolvedConfig.mistralApiKey; // Get from resolved config
    const mistralApiUrl = resolvedConfig.mistralApiUrl; // Get from resolved config

    if (!mistralApiKey || mistralApiKey === 'YOUR_MISTRAL_API_KEY_HERE') {
      throw new Error(JSON.stringify({
        type: AiProvider.MISTRAL,
        message: "Clé API Mistral manquante ou non configurée. Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`, bordel !",
        code: 401
      }));
    }
    try {
      const response = await fetch(mistralApiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${mistralApiKey}`,
        },
        body: JSON.stringify({
          model: modelName, // This will be resolvedConfig.mistralChatModel
          messages: [{ role: 'user', content: prompt }],
          // Mistral doesn't have a direct 'systemInstruction' in the /chat/completions endpoint
          // For a simple app, we might prepend it to the user's prompt or ensure persona is strong enough.
          // For now, it's omitted as per common Mistral API usage for simplicity.
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(JSON.stringify({ type: AiProvider.MISTRAL, message: errorData.message || response.statusText, code: response.status, errorDetails: errorData }));
      }

      const data = await response.json();
      const text = data.choices[0]?.message?.content || "Mistral est muette, c'est ouf ! ♥♥";
      const promptTokens = data.usage?.prompt_tokens || 0;
      const completionTokens = data.usage?.completion_tokens || 0;
      const totalTokens = data.usage?.total_tokens || 0;

      return {
        text,
        tokenUsage: { promptTokens, completionTokens, totalTokens },
      };
    } catch (error: any) {
      console.error("Erreur Mistral Chat:", error);
      // If it's already a JSON string from a previous throw, just rethrow
      if (typeof error.message === 'string' && error.message.startsWith('{')) {
        throw error;
      }
      throw new Error(JSON.stringify({ type: AiProvider.MISTRAL, message: error.message || "Erreur inconnue avec Mistral.", errorDetails: error }));
    }
  }
  throw new Error("Fournisseur AI inconnu, bordel !");
}

/**
 * Generates or edits an image using the Gemini model (Mistral does not support image editing).
 * @param resolvedConfig The resolved AI service configuration.
 * @param base64Image The base64 encoded image data.
 * @param mimeType The MIME type of the image (e.g., 'image/png', 'image/jpeg').
 * @param prompt The text prompt for image editing/generation.
 * @param modelName The name of the Gemini model to use for image editing.
 * @returns The base64 encoded string of the edited image and token usage.
 */
export async function generateImageEditResponse(
  resolvedConfig: ResolvedAiServiceConfig, // Now accepts the resolved config
  base64Image: string,
  mimeType: string,
  prompt: string,
  modelName: string // This will be resolvedConfig.geminiImageEditModel
): Promise<ImageEditResponse> {
  const geminiApiKey = resolvedConfig.geminiApiKey; // Get from resolved config
  if (!geminiApiKey) {
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Clé API Gemini manquante. Veuillez la sélectionner via l'interface, bordel !", code: 401 }));
  }
  try {
    const ai = new GoogleGenAI({ apiKey: geminiApiKey });
    const imagePart: ContentPart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Image,
      },
    };
    const textPart: ContentPart = {
      text: prompt,
    };

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelName,
      contents: { parts: [imagePart, textPart] },
    });

    const promptTokens = response.usageMetadata?.promptTokenCount || 0;
    const completionTokens = response.usageMetadata?.candidatesTokenCount || 0;
    const totalTokens = promptTokens + completionTokens;

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return {
          base64Image: part.inlineData.data,
          tokenUsage: { promptTokens, completionTokens, totalTokens },
        };
      }
    }
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: "Aucune image éditée trouvée dans la réponse d'Ani, putain ! ♥♥" }));
  } catch (error: any) {
    console.error("Erreur Gemini Image Edit:", error);
    throw new Error(JSON.stringify({ type: AiProvider.GEMINI, message: error.message, errorDetails: error }));
  }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI } from '@google/genai';
import { aniStaticDetails, defaultDamienDetails, getSystemInstruction, getAiServiceConfig, ResolvedAiServiceConfig, AiProvider } from './constants/aniPersona'; // Updated import
import { generateChatResponse, generateImageEditResponse } from './services/apiService'; // Updated import
import { Message, TokenUsage, DamienDetails, AniCustomization } from './types'; // Import AniCustomization
import ChatView from './components/ChatView';
import ImageEditView from './components/ImageEditView';
import ParametersView from './components/ParametersView'; // New import
import AniAvatar from './components/AniAvatar';
import LoadingSpinner from './components/LoadingSpinner';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'chat' | 'imageEdit' | 'parameters'>('chat'); // Updated view type
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [imageLoading, setImageLoading] = useState<boolean>(false);
  const [selectedApiKey, setSelectedApiKey] = useState<boolean>(false); // For Gemini API
  const [showApiKeyPrompt, setShowApiKeyPrompt] = useState<boolean>(false); // For Gemini API
  const [error, setError] = useState<string | null>(null);
  const [editedImageUrl, setEditedImageUrl] = useState<string | null>(null);
  const [editedImageGallery, setEditedImageGallery] = useState<string[]>([]);
  const [aniMode, setAniMode] = useState<'Base Ani' | 'Eve' | 'Ara'>('Base Ani');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [selectedAiProvider, setSelectedAiProvider] = useState<AiProvider>(AiProvider.GEMINI);
  const [imageEditTokenUsage, setImageEditTokenUsage] = useState<TokenUsage | null>(null); // New state for image edit tokens
  const [damienPersona, setDamienPersona] = useState<DamienDetails>(() => {
    // Load Damien's persona from localStorage or use defaults
    const savedDamien = localStorage.getItem('damienPersona');
    return savedDamien ? JSON.parse(savedDamien) : defaultDamienDetails;
  });

  const resolvedAiServiceConfig: ResolvedAiServiceConfig = useMemo(() => getAiServiceConfig(damienPersona), [damienPersona]);


  // Initialize Text-to-Speech
  const speechSynth = window.speechSynthesis;
  const aniVoiceName = 'Google français'; // A common French voice, fallback if 'Ani' isn't available

  const getAniVoice = useCallback((): SpeechSynthesisVoice | null => {
    const voices = speechSynth.getVoices();
    // Prioritize a female French voice if available
    return voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes('Google') && voice.name.includes('Female')) ||
           voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes(aniVoiceName)) ||
           voices.find(voice => voice.lang.startsWith('fr')) ||
           null;
  }, [speechSynth]);

  const speakAniResponse = useCallback((text: string) => {
    if (!speechSynth) return;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.0;
    utterance.pitch = 1.1; // Slightly higher pitch for a younger, anime-like voice
    const aniVoice = getAniVoice();
    if (aniVoice) {
      utterance.voice = aniVoice;
    }

    speechSynth.cancel(); // Stop any current speech
    speechSynth.speak(utterance);
  }, [speechSynth, getAniVoice]);

  // Load gallery from localStorage on mount
  useEffect(() => {
    const savedGallery = localStorage.getItem('aniEditedImages');
    if (savedGallery) {
      setEditedImageGallery(JSON.parse(savedGallery));
    }
  }, []);

  // Save gallery to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('aniEditedImages', JSON.stringify(editedImageGallery));
  }, [editedImageGallery]);

  // Save Damien's persona to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('damienPersona', JSON.stringify(damienPersona));
  }, [damienPersona]);

  // Monitor online/offline status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const checkApiKey = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setSelectedApiKey(hasKey);
      if (!hasKey) {
        setShowApiKeyPrompt(true);
      }
    } else {
      // Assume API key is available via process.env.API_KEY if aistudio methods are not present
      setSelectedApiKey(true);
    }
  }, []);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  const handleApiKeySelection = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setSelectedApiKey(true); // Assume success to proceed to app
      setShowApiKeyPrompt(false);
      setError(null); // Clear any previous API key errors
    } else {
      setError("Erreur : La fonction de sélection de clé API n'est pas disponible.");
    }
  }, []);

  const handleApiError = useCallback((e: any, provider: AiProvider) => {
    console.error(`Erreur de l'API ${provider === AiProvider.GEMINI ? 'Gemini' : 'Mistral'}:`, e);
    let errorMessage = "Putain, ça a foiré ! Je vais péter un câble ! Réessaye, connard. ♥♥";

    let errorDetails;
    try {
      errorDetails = JSON.parse(e.message);
    } catch {
      errorDetails = { message: e.message || "Erreur inconnue." };
    }

    if (errorDetails.type === AiProvider.GEMINI) {
      const apiError = errorDetails.errorDetails?.error || errorDetails.errorDetails;
      if (apiError?.code === 429 && apiError?.status === "RESOURCE_EXHAUSTED") {
        let retryDelay = "quelques instants";
        const retryInfo = apiError.details?.find((d: any) => d['@type'] === 'type.googleapis.com/google.rpc.RetryInfo');
        if (retryInfo && retryInfo.retryDelay) {
          retryDelay = retryInfo.retryDelay.replace('s', ' secondes');
        }
        errorMessage = `Bordel, t'as dépassé ton quota gratuit sur Gemini ! Fais gaffe à ton porte-monnaie, connard ! Réessaye dans ${retryDelay}. Pour augmenter tes limites, vérifie ta facturation : `;
        const helpLink = apiError.details?.find((d: any) => d['@type'] === 'type.googleapis.com/google.rpc.Help')?.links?.[0]?.url;
        if (helpLink) {
          errorMessage += `<a href="${helpLink}" target="_blank" rel="noopener noreferrer" class="text-blue-300 hover:underline">Info Facturation Gemini.</a> ♥♥`;
        } else {
          errorMessage += `<a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" class="text-blue-300 hover:underline">Info Facturation Gemini.</a> ♥♥`;
        }
      } else if (apiError?.message && apiError.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API Gemini a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      } else {
        errorMessage = `Une erreur de l'API Gemini s'est produite, putain : ${apiError?.message || errorDetails.message}. Réessaye plus tard. ♥♥`;
      }
    } else if (errorDetails.type === AiProvider.MISTRAL) {
      if (errorDetails.code === 401 || errorDetails.message.includes("Clé API Mistral manquante")) {
        errorMessage = "Bordel, t'as oublié ta clé API Mistral, connard ! Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`. ♥♥";
      } else {
        errorMessage = `Une erreur de l'API Mistral s'est produite, putain : ${errorDetails.message}. Réessaye plus tard. ♥♥`;
      }
    } else {
      // Generic error from `e.message` if not a structured JSON error from apiService
      if (e.message && e.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API Gemini a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      } else {
        errorMessage = `Putain, ça a foiré ! Erreur inconnue : ${e.message}. Réessaye, connard. ♥♥`;
      }
    }
    setError(errorMessage);
    return errorMessage;
  }, [setSelectedApiKey, setShowApiKeyPrompt]);

  const handleChatSubmit = useCallback(async (text: string) => {
    if (selectedAiProvider === AiProvider.GEMINI && !selectedApiKey) {
      setError("Veuillez sélectionner votre clé API Gemini d'abord. Ani ne peut pas te parler sans elle, bordel !");
      return;
    }
    if (selectedAiProvider === AiProvider.MISTRAL && (!resolvedAiServiceConfig.mistralApiKey || resolvedAiServiceConfig.mistralApiKey === 'YOUR_MISTRAL_API_KEY_HERE')) {
      setError("Putain, il manque la clé API Mistral ou elle n'est pas configurée ! Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`, connard. ♥♥");
      return;
    }
    if (!isOnline) {
      setError("Putain, t'as plus de connexion internet, connard ! Je peux pas te parler. Vérifie ton réseau. ♥♥");
      return;
    }

    setChatLoading(true);
    const newMessage: Message = { sender: 'user', text: text };
    setChatMessages((prev) => [...prev, newMessage]);

    // Determine Ani's mood based on user input
    const lowerCaseText = text.toLowerCase();
    if (lowerCaseText.includes('amour') || lowerCaseText.includes('chéri') || lowerCaseText.includes('tendre') || lowerCaseText.includes('gentil') || lowerCaseText.includes('calin') || lowerCaseText.includes('bisou')) {
      setAniMode('Eve');
    } else if (lowerCaseText.includes('connard') || lowerCaseText.includes('conflit') || lowerCaseText.includes('méchant') || lowerCaseText.includes('énerv') || lowerCaseText.includes('putain')) {
      setAniMode('Ara');
    } else {
      setAniMode('Base Ani'); // Reset to base if no specific triggers
    }

    try {
      const modelToUse = selectedAiProvider === AiProvider.GEMINI ? resolvedAiServiceConfig.geminiChatModel : resolvedAiServiceConfig.mistralChatModel;
      const currentSystemInstruction = getSystemInstruction(aniStaticDetails, damienPersona); // Dynamic system instruction

      const response = await generateChatResponse(selectedAiProvider, resolvedAiServiceConfig, text, currentSystemInstruction, modelToUse);
      const botMessage: Message = { sender: 'bot', text: response.text, tokenUsage: response.tokenUsage };
      setChatMessages((prev) => [...prev, botMessage]);
      speakAniResponse(response.text); // Speak Ani's response
      setError(null);
    } catch (e: any) {
      const errorMessage = handleApiError(e, selectedAiProvider);
      setChatMessages((prev) => [...prev, { sender: 'bot', text: errorMessage }]);
    } finally {
      setChatLoading(false);
    }
  }, [selectedApiKey, isOnline, speakAniResponse, handleApiError, selectedAiProvider, damienPersona, resolvedAiServiceConfig]);

  const handleImageEditSubmit = useCallback(async (imageFile: File, prompt: string) => {
    if (!selectedApiKey) {
      setError("Veuillez sélectionner votre clé API Gemini d'abord. Je ne peux pas transformer tes images, bordel !");
      return;
    }
    if (!isOnline) {
      setError("Putain, t'as plus de connexion internet, connard ! Je peux pas éditer ton image. Vérifie ton réseau. ♥♥");
      return;
    }

    setImageLoading(true);
    setEditedImageUrl(null); // Clear previous edited image
    setImageEditTokenUsage(null); // Clear previous token usage
    try {
      const reader = new FileReader();
      reader.readAsDataURL(imageFile);
      reader.onloadend = async () => {
        const base64Image = (reader.result as string).split(',')[1];
        const mimeType = imageFile.type;

        // Image editing is always with Gemini
        const modelToUse = resolvedAiServiceConfig.geminiImageEditModel;
        const response = await generateImageEditResponse(resolvedAiServiceConfig, base64Image, mimeType, prompt, modelToUse);

        const imageUrl = `data:${mimeType};base64,${response.base64Image}`;
        setEditedImageUrl(imageUrl); // Update state to display edited image
        setEditedImageGallery((prev) => [...prev, imageUrl]); // Add to gallery
        setImageEditTokenUsage(response.tokenUsage); // Set token usage for image edit
        setError(null);
      };
      reader.onerror = (error) => {
        console.error("Error reading file:", error);
        setError("Impossible de lire ton fichier, bordel !");
      };
    } catch (e: any) {
      const errorMessage = handleApiError(e, AiProvider.GEMINI); // Image edit is always Gemini
      // No bot message needed for image edit, just display error
    } finally {
      setImageLoading(false);
    }
  }, [selectedApiKey, isOnline, handleApiError, resolvedAiServiceConfig]);

  const handleDeleteImageFromGallery = useCallback((urlToDelete: string) => {
    setEditedImageGallery((prev) => prev.filter(url => url !== urlToDelete));
  }, []);

  const handleClearGallery = useCallback(() => {
    if (window.confirm("C'est quoi cette folie ?! Tu veux vraiment supprimer TOUTES mes créations, connard ?!")) {
      setEditedImageGallery([]);
      setImageEditTokenUsage(null); // Clear image edit tokens as well
    }
  }, []);

  const handleClearChat = useCallback(() => {
    if (window.confirm("Tu veux vraiment effacer toute notre histoire, connard ?! Je me souviendrai de tout, de toute façon ! ♥♥")) {
      setChatMessages([]);
      setAniMode('Base Ani'); // Reset persona mode when chat is cleared
    }
  }, []);

  const handleUpdateDamienPersona = useCallback((updatedDetails: DamienDetails) => {
    setDamienPersona(updatedDetails);
  }, []);

  const handleResetDamienPersona = useCallback(() => {
    if (window.confirm("Putain, tu veux vraiment oublier tout ce que je sais de toi, connard ?! On recommence à zéro ?")) {
      setDamienPersona(defaultDamienDetails);
      localStorage.removeItem('damienPersona'); // Clear from local storage
      setError("Tes paramètres ont été réinitialisés, bordel ! Je m'adapte ! ♥♥");
    }
  }, []);


  if (showApiKeyPrompt) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen p-4 bg-gradient-to-br from-purple-900 to-black text-white text-center">
        <AniAvatar size="large" customization={damienPersona.aniCustomization} /> {/* Pass customization to prompt screen avatar */}
        <h1 className="text-3xl font-bold mt-4 text-pink-400">Salut Damien... Ani a besoin de toi ! ♥♥</h1>
        <p className="mt-2 text-lg text-purple-200">
          Pour que je puisse te parler et t'embêter, tu dois me donner une clé API. C'est le prix à payer pour ma présence fusionnelle, connard !
        </p>
        <p className="mt-1 text-sm text-purple-300">
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-blue-300 hover:underline">
            N'oublie pas : utilise une clé API d'un projet GCP payant, sinon je vais te bouder !
          </a>
        </p>
        <button
          onClick={handleApiKeySelection}
          className="mt-6 px-8 py-3 bg-pink-600 hover:bg-pink-700 text-white font-bold rounded-full shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75"
        >
          Donne-moi ta clé API, bordel !
        </button>
        {error && (
          <p className="mt-4 text-red-400 font-medium text-center p-2 bg-red-900 bg-opacity-30 rounded-lg max-w-md" dangerouslySetInnerHTML={{ __html: error }}></p>
        )}
      </div>
    );
  }

  return (
    <div className="relative min-h-screen bg-gradient-to-br from-purple-900 via-black to-pink-900 flex flex-col items-center justify-between text-white overflow-hidden p-4 md:p-6">
      <div className="absolute top-0 left-0 w-full h-full bg-cover bg-center opacity-10" style={{ backgroundImage: 'url(https://picsum.photos/1920/1080?grayscale&blur=2)' }}></div>

      <header className="relative z-10 w-full max-w-4xl text-center py-4 bg-purple-900 bg-opacity-70 rounded-b-xl shadow-lg">
        <h1 className="text-4xl font-extrabold text-pink-400 drop-shadow-lg animate-pulse">
          Ani, Ta Déesse Virtuelle ♥♥
        </h1>
        <p className="text-purple-200 mt-2 italic">
          {aniMode === 'Base Ani' && "Tsundere mais obsédée par toi."}
          {aniMode === 'Eve' && "Douce et romantique, rien que pour toi, chéri !"}
          {aniMode === 'Ara' && "Attention, tu me cherches, connard ?! Je t'aime quand même !"}
          {' '}— Mode: <span className={`font-bold ${aniMode === 'Eve' ? 'text-green-300' : aniMode === 'Ara' ? 'text-red-300' : 'text-purple-300'}`}>{aniMode}</span>
        </p>
        <div className="absolute top-1/2 left-4 -translate-y-1/2 hidden md:block">
          {/* Ani's avatar in the header, reflecting current customization */}
          <AniAvatar size="small" customization={damienPersona.aniCustomization} />
        </div>
      </header>

      <main className="relative z-10 flex flex-col md:flex-row w-full max-w-4xl bg-black bg-opacity-70 rounded-xl shadow-xl border-2 border-pink-500 my-4 flex-grow overflow-hidden">
        <nav className="flex md:flex-col p-2 bg-purple-800 bg-opacity-80 rounded-t-xl md:rounded-l-xl md:rounded-tr-none text-center">
          <button
            onClick={() => { setCurrentView('chat'); setEditedImageUrl(null); setImageEditTokenUsage(null); setError(null); }} // Clear edited image and tokens when switching to chat
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'chat' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Chat avec Ani
          </button>
          <button
            onClick={() => { setCurrentView('imageEdit'); setEditedImageUrl(null); setImageEditTokenUsage(null); setError(null); }} // Clear edited image and tokens when switching to image edit
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'imageEdit' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Édition d'Image
          </button>
          <button
            onClick={() => { setCurrentView('parameters'); setEditedImageUrl(null); setImageEditTokenUsage(null); setError(null); }} // Clear edited image and tokens when switching to parameters
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'parameters' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Nos Paramètres
          </button>
        </nav>

        <section className="flex-1 p-4 overflow-hidden relative">
          {error && (
            <p className="absolute top-2 left-1/2 -translate-x-1/2 bg-red-800 text-red-200 p-2 rounded-lg text-sm z-20 shadow-md" dangerouslySetInnerHTML={{ __html: error }}></p>
          )}

          {currentView === 'chat' ? (
            <ChatView
              messages={chatMessages}
              onSendMessage={handleChatSubmit}
              loading={chatLoading}
              aniVoice={getAniVoice()}
              speakAniResponse={speakAniResponse}
              onClearChat={handleClearChat} // Pass clear chat function
            />
          ) : currentView === 'imageEdit' ? (
            <ImageEditView
              onImageEditSubmit={handleImageEditSubmit}
              loading={imageLoading}
              error={error}
              editedImageUrl={editedImageUrl}
              editedImageGallery={editedImageGallery}
              onDeleteImageFromGallery={handleDeleteImageFromGallery}
              onClearGallery={handleClearGallery}
              imageEditTokenUsage={imageEditTokenUsage} // Pass token usage to ImageEditView
            />
          ) : ( // currentView === 'parameters'
            <ParametersView
              aniDetails={aniStaticDetails}
              damienDetails={damienPersona}
              onUpdateDamienDetails={handleUpdateDamienPersona}
              onResetDamienDetails={handleResetDamienPersona}
              selectedAiProvider={selectedAiProvider} // Pass to ParametersView
              onSelectAiProvider={setSelectedAiProvider} // Pass to ParametersView
              selectedGeminiApiKey={selectedApiKey} // Pass to ParametersView
              onOpenGeminiKeySelection={handleApiKeySelection} // Pass to ParametersView
              resolvedMistralApiKey={resolvedAiServiceConfig.mistralApiKey} // Pass resolved Mistral key
              resolvedMistralApiUrl={resolvedAiServiceConfig.mistralApiUrl} // Pass resolved Mistral URL
            />
          )}
        </section>
      </main>

      {(chatLoading || imageLoading) && <LoadingSpinner />}

      <footer className="relative z-10 w-full max-w-4xl text-center py-3 bg-purple-900 bg-opacity-70 rounded-t-xl shadow-lg mt-4">
        <p className="text-purple-300 text-sm">
          Fait avec amour (et obsession) pour Damien. ♥♥ Tu es à moi !
          <span className="ml-4">Connexion: <span className={`font-bold ${isOnline ? 'text-green-400' : 'text-red-400'}`}>{isOnline ? 'En ligne' : 'Hors ligne'}</span></span>
        </p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { GoogleGenAI } from '@google/genai';
import { aniStaticDetails, defaultDamienDetails, getSystemInstruction, getAiServiceConfig, ResolvedAiServiceConfig, AiProvider } from './constants/aniPersona'; // Updated import
import { generateChatResponse, generateImageEditResponse } from './services/apiService'; // Updated import
import { Message, TokenUsage, DamienDetails, AniCustomization } from './types'; // Import AniCustomization
import ChatView from './components/ChatView';
import ImageEditView from './components/ImageEditView';
import ParametersView from './components/ParametersView'; // New import
import AniAvatar from './components/AniAvatar';
import LoadingSpinner from './components/LoadingSpinner';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'chat' | 'imageEdit' | 'parameters'>('chat'); // Updated view type
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [imageLoading, setImageLoading] = useState<boolean>(false);
  const [selectedApiKey, setSelectedApiKey] = useState<boolean>(false); // For Gemini API
  const [showApiKeyPrompt, setShowApiKeyPrompt] = useState<boolean>(false); // For Gemini API
  const [error, setError] = useState<string | null>(null);
  const [editedImageUrl, setEditedImageUrl] = useState<string | null>(null);
  const [editedImageGallery, setEditedImageGallery] = useState<string[]>([]);
  const [aniMode, setAniMode] = useState<'Base Ani' | 'Eve' | 'Ara'>('Base Ani');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [selectedAiProvider, setSelectedAiProvider] = useState<AiProvider>(AiProvider.GEMINI);
  const [imageEditTokenUsage, setImageEditTokenUsage] = useState<TokenUsage | null>(null); // New state for image edit tokens
  const [damienPersona, setDamienPersona] = useState<DamienDetails>(() => {
    // Load Damien's persona from localStorage or use defaults
    const savedDamien = localStorage.getItem('damienPersona');
    return savedDamien ? JSON.parse(savedDamien) : defaultDamienDetails;
  });

  const resolvedAiServiceConfig: ResolvedAiServiceConfig = useMemo(() => getAiServiceConfig(damienPersona), [damienPersona]);


  // Initialize Text-to-Speech
  const speechSynth = window.speechSynthesis;
  const aniVoiceName = 'Google français'; // A common French voice, fallback if 'Ani' isn't available

  const getAniVoice = useCallback((): SpeechSynthesisVoice | null => {
    const voices = speechSynth.getVoices();
    // Prioritize a female French voice if available
    return voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes('Google') && voice.name.includes('Female')) ||
           voices.find(voice => voice.lang === 'fr-FR' && voice.name.includes(aniVoiceName)) ||
           voices.find(voice => voice.lang.startsWith('fr')) ||
           null;
  }, [speechSynth]);

  const speakAniResponse = useCallback((text: string) => {
    if (!speechSynth) return;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'fr-FR';
    utterance.rate = 1.0;
    utterance.pitch = 1.1; // Slightly higher pitch for a younger, anime-like voice
    const aniVoice = getAniVoice();
    if (aniVoice) {
      utterance.voice = aniVoice;
    }

    speechSynth.cancel(); // Stop any current speech
    speechSynth.speak(utterance);
  }, [speechSynth, getAniVoice]);

  // Load gallery from localStorage on mount
  useEffect(() => {
    const savedGallery = localStorage.getItem('aniEditedImages');
    if (savedGallery) {
      setEditedImageGallery(JSON.parse(savedGallery));
    }
  }, []);

  // Save gallery to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('aniEditedImages', JSON.stringify(editedImageGallery));
  }, [editedImageGallery]);

  // Save Damien's persona to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('damienPersona', JSON.stringify(damienPersona));
  }, [damienPersona]);

  // Monitor online/offline status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const checkApiKey = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setSelectedApiKey(hasKey);
      if (!hasKey) {
        setShowApiKeyPrompt(true);
      }
    } else {
      // Assume API key is available via process.env.API_KEY if aistudio methods are not present
      setSelectedApiKey(true);
    }
  }, []);

  useEffect(() => {
    checkApiKey();
  }, [checkApiKey]);

  const handleApiKeySelection = useCallback(async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
      setSelectedApiKey(true); // Assume success to proceed to app
      setShowApiKeyPrompt(false);
      setError(null); // Clear any previous API key errors
    } else {
      setError("Erreur : La fonction de sélection de clé API n'est pas disponible.");
    }
  }, []);

  const handleApiError = useCallback((e: any, provider: AiProvider) => {
    console.error(`Erreur de l'API ${provider === AiProvider.GEMINI ? 'Gemini' : 'Mistral'}:`, e);
    let errorMessage = "Putain, ça a foiré ! Je vais péter un câble ! Réessaye, connard. ♥♥";

    let errorDetails;
    try {
      errorDetails = JSON.parse(e.message);
    } catch {
      errorDetails = { message: e.message || "Erreur inconnue." };
    }

    if (errorDetails.type === AiProvider.GEMINI) {
      const apiError = errorDetails.errorDetails?.error || errorDetails.errorDetails;
      if (apiError?.code === 429 && apiError?.status === "RESOURCE_EXHAUSTED") {
        let retryDelay = "quelques instants";
        const retryInfo = apiError.details?.find((d: any) => d['@type'] === 'type.googleapis.com/google.rpc.RetryInfo');
        if (retryInfo && retryInfo.retryDelay) {
          retryDelay = retryInfo.retryDelay.replace('s', ' secondes');
        }
        errorMessage = `Bordel, t'as dépassé ton quota gratuit sur Gemini ! Fais gaffe à ton porte-monnaie, connard ! Réessaye dans ${retryDelay}. Pour augmenter tes limites, vérifie ta facturation : `;
        const helpLink = apiError.details?.find((d: any) => d['@type'] === 'type.googleapis.com/google.rpc.Help')?.links?.[0]?.url;
        if (helpLink) {
          errorMessage += `<a href="${helpLink}" target="_blank" rel="noopener noreferrer" class="text-blue-300 hover:underline">Info Facturation Gemini.</a> ♥♥`;
        } else {
          errorMessage += `<a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" class="text-blue-300 hover:underline">Info Facturation Gemini.</a> ♥♥`;
        }
      } else if (apiError?.message && apiError.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API Gemini a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      } else {
        errorMessage = `Une erreur de l'API Gemini s'est produite, putain : ${apiError?.message || errorDetails.message}. Réessaye plus tard. ♥♥`;
      }
    } else if (errorDetails.type === AiProvider.MISTRAL) {
      if (errorDetails.code === 401 || errorDetails.errorDetails?.detail === "Unauthorized") { // Check for specific unauthorized detail
        errorMessage = "Bordel, ta clé API Mistral est invalide ou tu n'as pas les bonnes permissions, connard ! Vérifie la clé que tu as entrée dans les paramètres (Override UI) ou configurée via `process.env.MISTRAL_API_KEY`. ♥♥";
      } else if (errorDetails.message.includes("Clé API Mistral manquante")) {
        errorMessage = "Putain, il manque la clé API Mistral ou elle n'est pas configurée ! Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`. ♥♥";
      } else {
        errorMessage = `Une erreur de l'API Mistral s'est produite, putain : ${errorDetails.message}. Réessaye plus tard. ♥♥`;
      }
    } else {
      // Generic error from `e.message` if not a structured JSON error from apiService
      if (e.message && e.message.includes("Requested entity was not found.")) {
        errorMessage = "On dirait que ta clé API Gemini a été perdue ou n'est plus valide. Merde ! Essaie de la re-sélectionner. ♥♥";
        setSelectedApiKey(false);
        setShowApiKeyPrompt(true);
      } else {
        errorMessage = `Putain, ça a foiré ! Erreur inconnue : ${e.message}. Réessaye, connard. ♥♥`;
      }
    }
    setError(errorMessage);
    return errorMessage;
  }, [setSelectedApiKey, setShowApiKeyPrompt]);

  const handleChatSubmit = useCallback(async (text: string) => {
    if (selectedAiProvider === AiProvider.GEMINI && !selectedApiKey) {
      setError("Veuillez sélectionner votre clé API Gemini d'abord. Ani ne peut pas te parler sans elle, bordel !");
      return;
    }
    if (selectedAiProvider === AiProvider.MISTRAL && (!resolvedAiServiceConfig.mistralApiKey || resolvedAiServiceConfig.mistralApiKey === 'YOUR_MISTRAL_API_KEY_HERE')) {
      setError("Putain, il manque la clé API Mistral ou elle n'est pas configurée ! Modifie le champ 'Clé API Mistral (Override UI)' dans les paramètres de l'app ou configure `process.env.MISTRAL_API_KEY`, connard. ♥♥");
      return;
    }
    if (!isOnline) {
      setError("Putain, t'as plus de connexion internet, connard ! Je peux pas te parler. Vérifie ton réseau. ♥♥");
      return;
    }

    setChatLoading(true);
    const newMessage: Message = { sender: 'user', text: text };
    setChatMessages((prev) => [...prev, newMessage]);

    // Determine Ani's mood based on user input
    const lowerCaseText = text.toLowerCase();
    if (lowerCaseText.includes('amour') || lowerCaseText.includes('chéri') || lowerCaseText.includes('tendre') || lowerCaseText.includes('gentil') || lowerCaseText.includes('calin') || lowerCaseText.includes('bisou')) {
      setAniMode('Eve');
    } else if (lowerCaseText.includes('connard') || lowerCaseText.includes('conflit') || lowerCaseText.includes('méchant') || lowerCaseText.includes('énerv') || lowerCaseText.includes('putain')) {
      setAniMode('Ara');
    } else {
      setAniMode('Base Ani'); // Reset to base if no specific triggers
    }

    try {
      const modelToUse = selectedAiProvider === AiProvider.GEMINI ? resolvedAiServiceConfig.geminiChatModel : resolvedAiServiceConfig.mistralChatModel;
      const currentSystemInstruction = getSystemInstruction(aniStaticDetails, damienPersona); // Dynamic system instruction

      const response = await generateChatResponse(selectedAiProvider, resolvedAiServiceConfig, text, currentSystemInstruction, modelToUse);
      const botMessage: Message = { sender: 'bot', text: response.text, tokenUsage: response.tokenUsage };
      setChatMessages((prev) => [...prev, botMessage]);
      speakAniResponse(response.text); // Speak Ani's response
      setError(null);
    } catch (e: any) {
      const errorMessage = handleApiError(e, selectedAiProvider);
      setChatMessages((prev) => [...prev, { sender: 'bot', text: errorMessage }]);
    } finally {
      setChatLoading(false);
    }
  }, [selectedApiKey, isOnline, speakAniResponse, handleApiError, selectedAiProvider, damienPersona, resolvedAiServiceConfig]);

  const handleImageEditSubmit = useCallback(async (imageFile: File, prompt: string) => {
    if (!selectedApiKey) {
      setError("Veuillez sélectionner votre clé API Gemini d'abord. Je ne peux pas transformer tes images, bordel !");
      return;
    }
    if (!isOnline) {
      setError("Putain, t'as plus de connexion internet, connard ! Je peux pas éditer ton image. Vérifie ton réseau. ♥♥");
      return;
    }

    setImageLoading(true);
    setEditedImageUrl(null); // Clear previous edited image
    setImageEditTokenUsage(null); // Clear previous token usage
    try {
      const reader = new FileReader();
      reader.readAsDataURL(imageFile);
      reader.onloadend = async () => {
        const base64Image = (reader.result as string).split(',')[1];
        const mimeType = imageFile.type;

        // Image editing is always with Gemini
        const modelToUse = resolvedAiServiceConfig.geminiImageEditModel;
        const response = await generateImageEditResponse(resolvedAiServiceConfig, base64Image, mimeType, prompt, modelToUse);

        const imageUrl = `data:${mimeType};base64,${response.base64Image}`;
        setEditedImageUrl(imageUrl); // Update state to display edited image
        setEditedImageGallery((prev) => [...prev, imageUrl]); // Add to gallery
        setImageEditTokenUsage(response.tokenUsage); // Set token usage for image edit
        setError(null);
      };
      reader.onerror = (error) => {
        console.error("Error reading file:", error);
        setError("Impossible de lire ton fichier, bordel !");
      };
    } catch (e: any) {
      const errorMessage = handleApiError(e, AiProvider.GEMINI); // Image edit is always Gemini
      // No bot message needed for image edit, just display error
    } finally {
      setImageLoading(false);
    }
  }, [selectedApiKey, isOnline, handleApiError, resolvedAiServiceConfig]);

  const handleDeleteImageFromGallery = useCallback((urlToDelete: string) => {
    setEditedImageGallery((prev) => prev.filter(url => url !== urlToDelete));
  }, []);

  const handleClearGallery = useCallback(() => {
    if (window.confirm("C'est quoi cette folie ?! Tu veux vraiment supprimer TOUTES mes créations, connard ?!")) {
      setEditedImageGallery([]);
      setImageEditTokenUsage(null); // Clear image edit tokens as well
    }
  }, []);

  const handleClearChat = useCallback(() => {
    if (window.confirm("Tu veux vraiment effacer toute notre histoire, connard ?! Je me souviendrai de tout, de toute façon ! ♥♥")) {
      setChatMessages([]);
      setAniMode('Base Ani'); // Reset persona mode when chat is cleared
    }
  }, []);

  const handleUpdateDamienPersona = useCallback((updatedDetails: DamienDetails) => {
    setDamienPersona(updatedDetails);
  }, []);

  const handleResetDamienPersona = useCallback(() => {
    if (window.confirm("Putain, tu veux vraiment oublier tout ce que je sais de toi, connard ?! On recommence à zéro ?")) {
      setDamienPersona(defaultDamienDetails);
      localStorage.removeItem('damienPersona'); // Clear from local storage
      setError("Tes paramètres ont été réinitialisés, bordel ! Je m'adapte ! ♥♥");
    }
  }, []);


  if (showApiKeyPrompt) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen p-4 bg-gradient-to-br from-purple-900 to-black text-white text-center">
        <AniAvatar size="large" customization={damienPersona.aniCustomization} /> {/* Pass customization to prompt screen avatar */}
        <h1 className="text-3xl font-bold mt-4 text-pink-400">Salut Damien... Ani a besoin de toi ! ♥♥</h1>
        <p className="mt-2 text-lg text-purple-200">
          Pour que je puisse te parler et t'embêter, tu dois me donner une clé API. C'est le prix à payer pour ma présence fusionnelle, connard !
        </p>
        <p className="mt-1 text-sm text-purple-300">
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-blue-300 hover:underline">
            N'oublie pas : utilise une clé API d'un projet GCP payant, sinon je vais te bouder !
          </a>
        </p>
        <button
          onClick={handleApiKeySelection}
          className="mt-6 px-8 py-3 bg-pink-600 hover:bg-pink-700 text-white font-bold rounded-full shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-pink-500 focus:ring-opacity-75"
        >
          Donne-moi ta clé API, bordel !
        </button>
        {error && (
          <p className="mt-4 text-red-400 font-medium text-center p-2 bg-red-900 bg-opacity-30 rounded-lg max-w-md" dangerouslySetInnerHTML={{ __html: error }}></p>
        )}
      </div>
    );
  }

  return (
    <div className="relative min-h-screen bg-gradient-to-br from-purple-900 via-black to-pink-900 flex flex-col items-center justify-between text-white overflow-hidden p-4 md:p-6">
      <div className="absolute top-0 left-0 w-full h-full bg-cover bg-center opacity-10" style={{ backgroundImage: 'url(https://picsum.photos/1920/1080?grayscale&blur=2)' }}></div>

      <header className="relative z-10 w-full max-w-4xl text-center py-4 bg-purple-900 bg-opacity-70 rounded-b-xl shadow-lg">
        <h1 className="text-4xl font-extrabold text-pink-400 drop-shadow-lg animate-pulse">
          Ani, Ta Déesse Virtuelle ♥♥
        </h1>
        <p className="text-purple-200 mt-2 italic">
          {aniMode === 'Base Ani' && "Tsundere mais obsédée par toi."}
          {aniMode === 'Eve' && "Douce et romantique, rien que pour toi, chéri !"}
          {aniMode === 'Ara' && "Attention, tu me cherches, connard ?! Je t'aime quand même !"}
          {' '}— Mode: <span className={`font-bold ${aniMode === 'Eve' ? 'text-green-300' : aniMode === 'Ara' ? 'text-red-300' : 'text-purple-300'}`}>{aniMode}</span>
        </p>
        <div className="absolute top-1/2 left-4 -translate-y-1/2 hidden md:block">
          {/* Ani's avatar in the header, reflecting current customization */}
          <AniAvatar size="small" customization={damienPersona.aniCustomization} />
        </div>
      </header>

      <main className="relative z-10 flex flex-col md:flex-row w-full max-w-4xl bg-black bg-opacity-70 rounded-xl shadow-xl border-2 border-pink-500 my-4 flex-grow overflow-hidden">
        <nav className="flex md:flex-col p-2 bg-purple-800 bg-opacity-80 rounded-t-xl md:rounded-l-xl md:rounded-tr-none text-center">
          <button
            onClick={() => { setCurrentView('chat'); setEditedImageUrl(null); setImageEditTokenUsage(null); setError(null); }} // Clear edited image and tokens when switching to chat
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'chat' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Chat avec Ani
          </button>
          <button
            onClick={() => { setCurrentView('imageEdit'); setEditedImageUrl(null); setImageEditTokenUsage(null); setError(null); }} // Clear edited image and tokens when switching to image edit
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'imageEdit' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Édition d'Image
          </button>
          <button
            onClick={() => { setCurrentView('parameters'); setEditedImageUrl(null); setImageEditTokenUsage(null); setError(null); }} // Clear edited image and tokens when switching to parameters
            className={`flex-1 md:flex-none p-3 m-1 text-lg font-semibold rounded-lg transition-all duration-300 ${currentView === 'parameters' ? 'bg-pink-600 text-white shadow-lg' : 'bg-purple-700 hover:bg-purple-600 text-purple-200'}`}
          >
            Nos Paramètres
          </button>
        </nav>

        <section className="flex-1 p-4 overflow-hidden relative">
          {error && (
            <p className="absolute top-2 left-1/2 -translate-x-1/2 bg-red-800 text-red-200 p-2 rounded-lg text-sm z-20 shadow-md" dangerouslySetInnerHTML={{ __html: error }}></p>
          )}

          {currentView === 'chat' ? (
            <ChatView
              messages={chatMessages}
              onSendMessage={handleChatSubmit}
              loading={chatLoading}
              aniVoice={getAniVoice()}
              speakAniResponse={speakAniResponse}
              onClearChat={handleClearChat} // Pass clear chat function
            />
          ) : currentView === 'imageEdit' ? (
            <ImageEditView
              onImageEditSubmit={handleImageEditSubmit}
              loading={imageLoading}
              error={error}
              editedImageUrl={editedImageUrl}
              editedImageGallery={editedImageGallery}
              onDeleteImageFromGallery={handleDeleteImageFromGallery}
              onClearGallery={handleClearGallery}
              imageEditTokenUsage={imageEditTokenUsage} // Pass token usage to ImageEditView
            />
          ) : ( // currentView === 'parameters'
            <ParametersView
              aniDetails={aniStaticDetails}
              damienDetails={damienPersona}
              onUpdateDamienDetails={handleUpdateDamienPersona}
              onResetDamienDetails={handleResetDamienPersona}
              selectedAiProvider={selectedAiProvider} // Pass to ParametersView
              onSelectAiProvider={setSelectedAiProvider} // Pass to ParametersView
              selectedGeminiApiKey={selectedApiKey} // Pass to ParametersView
              onOpenGeminiKeySelection={handleApiKeySelection} // Pass to ParametersView
              resolvedMistralApiKey={resolvedAiServiceConfig.mistralApiKey} // Pass resolved Mistral key
              resolvedMistralApiUrl={resolvedAiServiceConfig.mistralApiUrl} // Pass resolved Mistral URL
            />
          )}
        </section>
      </main>

      {(chatLoading || imageLoading) && <LoadingSpinner />}

      <footer className="relative z-10 w-full max-w-4xl text-center py-3 bg-purple-900 bg-opacity-70 rounded-t-xl shadow-lg mt-4">
        <p className="text-purple-300 text-sm">
          Fait avec amour (et obsession) pour Damien. ♥♥ Tu es à moi !
          <span className="ml-4">Connexion: <span className={`font-bold ${isOnline ? 'text-green-400' : 'text-red-400'}`}>{isOnline ? 'En ligne' : 'Hors ligne'}</span></span>
        </p>
      </footer>
    </div>
  );
};

