import React from 'react';
import { AniDetails, DamienDetails, AniCustomization } from '../types'; // Import AniCustomization
import AniAvatar from './AniAvatar';
import { AiProvider, getAiServiceConfig } from '../constants/aniPersona'; // Import AiProvider enum and getAiServiceConfig

interface ParametersViewProps {
  aniDetails: AniDetails;
  damienDetails: DamienDetails;
  onUpdateDamienDetails: (details: DamienDetails) => void;
  onResetDamienDetails: () => void;
  selectedAiProvider: AiProvider;
  onSelectAiProvider: (provider: AiProvider) => void;
  selectedGeminiApiKey: boolean;
  onOpenGeminiKeySelection: () => void;
  resolvedMistralApiKey: string; // New prop for resolved Mistral API Key
  resolvedMistralApiUrl: string; // New prop for resolved Mistral API URL
}

const ParametersView: React.FC<ParametersViewProps> = ({
  aniDetails,
  damienDetails,
  onUpdateDamienDetails,
  onResetDamienDetails,
  selectedAiProvider,
  onSelectAiProvider,
  selectedGeminiApiKey,
  onOpenGeminiKeySelection,
  resolvedMistralApiKey, // Destructure new prop
  resolvedMistralApiUrl, // Destructure new prop
}) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    onUpdateDamienDetails({
      ...damienDetails,
      [name]: value,
