const axios = require('axios');

const API_KEY = "UeySJi7dMG2Qk1J7xQrItXdswJo0u661";
const API_URL = "https://api.mistral.ai/v1/chat/completions";

async function callMistralAPI(prompt) {
    try {
        const response = await axios.post(
            API_URL,
            {
                model: "mistral-medium",
                messages: [
                    { role: "user", content: prompt }
                ],
            },
            {
                headers: {
                    "Authorization": `Bearer ${API_KEY}`,
                    "Content-Type": "application/json",
                },
            }
        );
        return response.data.choices[0].message.content;
    } catch (error) {
        console.error("Erreur lors de l'appel à l'API Mistral :", error.response?.data || error.message);
        throw error;
    }
}

// Exemple d'utilisation
const prompt = "Explique-moi comment fonctionne une API en termes simples.";
callMistralAPI(prompt)
    .then((result) => console.log("Réponse de l'API :", result))
    .catch((err) => console.error("Erreur :", err));

