export default ParametersView;

export interface Message {
  sender: 'user' | 'bot';
  text: string;
  image?: string; // Optional image URL for messages
  tokenUsage?: TokenUsage; // Optional token usage for bot messages
}

export interface TokenUsage {
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
}

export interface ChatHistoryEntry {
  role: 'user' | 'model' | 'system';
  parts: { text: string }[];
}

// For image editing, assuming base64 string
export interface ImagePart {
  inlineData: {
    mimeType: string;
    data: string; // Base64 encoded string
  };
}

export type ContentPart = { text: string } | ImagePart;

export interface ToolConfig {
  retrievalConfig?: {
    latLng: {
      latitude: number;
      longitude: number;
    };
  };
  // Add other tool configs if needed
}

// Interfaces for Ani's and Damien's persona details
